}

let parsed;
try {
  const cleaned = content.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { type: 'unknown', text: transcript };
}

const type = parsed.type || 'unknown';
const now = new Date();
const today = now.toISOString().substring(0, 10);

if (type === 'query') {
  // Map to same format as Parse Intent output
  const intent = parsed.intent || 'unknown';
  let apiType = 'fetch_dashboard';
  let apiUrl = 'https://n8n-n8n.0uvai5.easypanel.host/webhook/batutynas-dashboard-v2' + `?year=${now.getFullYear()}&month=${now.getMonth() + 1}`;
  let args = {};

  if (intent === 'available') {
    apiType = 'fetch_availability';
    const date = parsed.date || today;
    apiUrl = 'https://n8n-n8n.0uvai5.easypanel.host/webhook/batutynas-availability' + `?date=${date}`;
    args.date = date;
  } else if (intent === 'today') {
    args.filterDate = today;
  } else if (intent === 'tomorrow') {
    const tmrw = new Date(now); tmrw.setDate(tmrw.getDate() + 1);
    args.filterDate = tmrw.toISOString().substring(0, 10);
    apiUrl = 'https://n8n-n8n.0uvai5.easypanel.host/webhook/batutynas-dashboard-v2' + `?year=${tmrw.getFullYear()}&month=${tmrw.getMonth() + 1}`;
  } else if (intent === 'search') {
    args.searchQuery = (parsed.query || '').toLowerCase();
